import { useEffect, useState } from "react";
import type { Product } from "./schemas";

type ProductDetailsProps = { slug: string };

export function ProductDetails({ slug }: ProductDetailsProps) {
  const [product, setProduct] = useState<Product | null>(null);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    fetch(`/v1/products/${slug}`)
      .then((response) => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return response.json();
      })
      .then((data: Product) => {
        console.log(`showing ${data.name}`);
        setProduct(data);
      })
      .catch((err: Error) => setError(err));
  }, [slug]);

  if (error) return <p role="alert">Couldn't load this product.</p>;
  if (!product) return <p>Loading…</p>;
  return <h1>{product.name}</h1>;
}

import { useEffect, useState } from "react";
import type { Product } from "./schemas";

type ProductDetailsProps = { slug: string };

export function ProductDetails({ slug }: ProductDetailsProps) {
  const [product, setProduct] = useState<Product | null>(null);
  const [error, setError] = useState<Error | null>(null);

  useEffect(() => {
    const controller = new AbortController();

    fetch(`/v1/products/${slug}`, { signal: controller.signal })
      .then((response) => {
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return response.json();
      })
      .then((data: Product) => {
        console.log(`showing ${data.name}`);
        setProduct(data);
      })
      .catch((err: Error) => {
        if (err.name === "AbortError") {
          console.log(`aborted ${slug}`);
          return;
        }
        setError(err);
      });

    return () => controller.abort();
  }, [slug]);

  if (error) return <p role="alert">Couldn't load this product.</p>;
  if (!product) return <p>Loading…</p>;
  return <h1>{product.name}</h1>;
}

import { z } from "zod";

const BASE_URL = import.meta.env.VITE_API_URL ?? "/v1";

// An RFC 9457 problem. loose() keeps extra fields, like a 409's "available".
const Problem = z
  .object({
    type: z.string().default("about:blank"),
    title: z.string(),
    status: z.number().int(),
    detail: z.string().optional(),
    errors: z.record(z.string(), z.string()).optional(),
  })
  .loose();

export type Problem = z.infer<typeof Problem>;

export class ApiError extends Error {
  readonly status: number;
  readonly problem: Problem;
  readonly headers: Headers;

  constructor(problem: Problem, headers: Headers) {
    super(problem.detail ?? problem.title);
    this.name = "ApiError";
    this.status = problem.status;
    this.problem = problem;
    this.headers = headers;
  }
}

type ApiFetchOptions<T> = {
  schema: z.ZodType<T>;
  method?: "GET" | "POST" | "PUT" | "PATCH" | "DELETE";
  body?: unknown;
  headers?: Record<string, string>;
  signal?: AbortSignal;
  timeoutMs?: number;
};

export async function apiFetch<T>(path: string, options: ApiFetchOptions<T>): Promise<T> {
  const { schema, method = "GET", body, headers, signal, timeoutMs = 10_000 } = options;
  const timeout = AbortSignal.timeout(timeoutMs);

  const response = await fetch(`${BASE_URL}${path}`, {
    method,
    credentials: "include",
    headers: {
      Accept: "application/json",
      ...(body !== undefined && { "Content-Type": "application/json" }),
      ...headers,
    },
    body: body === undefined ? undefined : JSON.stringify(body),
    signal: signal ? AbortSignal.any([signal, timeout]) : timeout,
  });

  if (!response.ok) throw await toApiError(response);
  const data: unknown = response.status === 204 ? undefined : await response.json();
  return schema.parse(data);
}

async function toApiError(response: Response): Promise<ApiError> {
  const body: unknown = await response.json().catch(() => null);
  const parsed = Problem.safeParse(body);
  const problem = parsed.success
    ? parsed.data
    : { type: "about:blank", title: response.statusText || "Request failed", status: response.status };
  return new ApiError(problem, response.headers);
}

import { apiFetch } from "@/lib/api";
import { Product, ProductPage, type Category } from "./schemas";

export type ProductFilters = {
  category?: Category;
  q?: string;
  page?: number;
};

export function getProduct(slug: string, signal?: AbortSignal) {
  return apiFetch(`/products/${encodeURIComponent(slug)}`, { schema: Product, signal });
}

export function listProducts(filters: ProductFilters, signal?: AbortSignal) {
  const params = new URLSearchParams();
  if (filters.category) params.set("category", filters.category);
  if (filters.q) params.set("q", filters.q);
  if (filters.page) params.set("page", String(filters.page));
  return apiFetch(`/products?${params}`, { schema: ProductPage, signal });
}

import { z } from "zod";

const ProductSummary = z.object({
  slug: z.string(),
  name: z.string(),
  category: z.enum(["packs", "tents", "apparel", "cooking"]),
  priceCents: z.number().int(),
  imageUrl: z.string(),
  rating: z.object({ average: z.number(), count: z.number().int() }),
  inStock: z.boolean(),
});

// What a changed server might send: price as a string, and no inStock.
const fromServer = {
  slug: "hip-pack-5",
  name: "Hip Pack 5L",
  category: "packs",
  price: "39.00",
  imageUrl: "/images/products/hip-pack-5.webp",
  rating: { average: 4.2, count: 9 },
};

const result = ProductSummary.safeParse(fromServer);
console.log(result.success);
if (!result.success) console.log(z.prettifyError(result.error));

steps.body:
The Sharing State lesson split state into kinds, and server data was its own kind: a copy of something the server owns. A copy can go out of date, many components want the same piece of it, and it should load once and refresh on its own. **TanStack Query** is a library that keeps those copies for you, in one cache shared by the whole app, and does the work from part 1 that an effect left to you: loading and error states, aborting, no duplicate requests, retries, and refreshing.

## Setting it up

TanStack Query comes in one package for React, installed next to zod in the first example. The cache is a `QueryClient`. Make one for the whole app, in its own module so the router can use it too, and give it defaults:

```ts
import { QueryClient } from "@tanstack/react-query";
import { ApiError } from "@/lib/api";

export const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: 30_000,
      retry: (failureCount, error) => {
        if (error instanceof ApiError && error.status < 500) return false;
        return failureCount < 3;
      },
    },
  },
});
```

That's `src/app/queryClient.ts`. Then `main.tsx` wraps the app in a provider, so every component below it can reach the cache:

```tsx sketch
<QueryClientProvider client={queryClient}>
  <RouterProvider router={router} />
</QueryClientProvider>
```

## Keys name the data

Each entry in the cache has a **query key**, an array that names the data, like `["products", "detail", "hip-pack-5"]`. Two components that use the same key share one entry. If both ask while nothing is cached, TanStack Query sends one request and gives both the answer:

```diagram calling-apis-one-key
Three components, one key: one cache entry, and one request.
```

On the product page, the heading, the price, and the add-to-cart button each read the product with the same key. All three subscribe to one entry, and the entry makes one request. When the answer lands, all three render with it. The rest of the key's elements say which product, and they can hold objects too, like `["products", "list", { category: "tents", page: 2 }]`: TanStack Query compares keys by their contents, so a new object with the same filters finds the same entry.

## One place for each query

A query needs a key and a **query function**, the function that fetches the data. Writing both in every component that needs the product invites a typo in one key. `queryOptions` bundles them into one object you write once, in the second example, and pass everywhere: to the hooks, to the router's loaders in part 4, and to the cache when you change data in part 5. The query function receives a `signal`, which TanStack Query aborts when nobody needs the answer anymore, so the race from part 1 can't happen.

## Fresh, stale, and garbage collected

Two settings decide how long a copy is trusted and how long it's kept, and mixing them up is the most common TanStack Query mistake.

- **`staleTime`** is how long data counts as **fresh**. Fresh data comes straight from the cache, with no request. Once it's **stale**, the cache still shows it at once, but also fetches a new copy in the background when a component using it appears, when you come back to the browser window, or when the network reconnects. The default is 0, stale at once. This app makes it 30 seconds, so moving between pages doesn't refetch everything.
- **`gcTime`** is how long an entry nobody is using stays in memory before it's deleted. The default is 5 minutes. GC stands for garbage collection, freeing memory that's no longer needed.

Think of food in a fridge: `staleTime` is the best-before date, after which you still eat it but buy a fresh one on the way home, and `gcTime` is how long leftovers nobody touches sit before they're thrown out.

## Retries

When a query fails, TanStack Query tries again, three times by default, and waits longer before each try. Retrying helps when a server hiccups, but a 404 won't change on the fourth try. The `retry` function above gives up at once on any `ApiError` under 500, and tries three more times for the rest, as the default does.

The hook that reads a query is `useQuery`. The third example shows the states it gives a component.

