import { queryOptions } from "@tanstack/react-query";
import { getProduct, listProducts, type ProductFilters } from "./api";

export function productQuery(slug: string) {
  return queryOptions({
    queryKey: ["products", "detail", slug],
    queryFn: ({ signal }) => getProduct(slug, signal),
  });
}

export function productListQuery(filters: ProductFilters) {
  return queryOptions({
    queryKey: ["products", "list", filters],
    queryFn: ({ signal }) => listProducts(filters, signal),
  });
}

import { useQuery } from "@tanstack/react-query";
import { ApiError } from "@/lib/api";
import { formatPrice } from "@/lib/format";
import { productQuery } from "./queries";

type ProductSummaryCardProps = { slug: string };

export function ProductSummaryCard({ slug }: ProductSummaryCardProps) {
  const { data: product, isPending, isError, error, isFetching } = useQuery(productQuery(slug));

  if (isPending) return <p>Loading…</p>;
  if (isError) {
    const missing = error instanceof ApiError && error.status === 404;
    return <p role="alert">{missing ? "We don't sell that product." : "Couldn't load this product."}</p>;
  }

  return (
    <article aria-busy={isFetching}>
      <h2>{product.name}</h2>
      <p>{formatPrice(product.priceCents)}</p>
      {!product.inStock && <p>Out of stock</p>}
    </article>
  );
}

steps.body:
Checking `isPending` and `isError` in every component works, but it spreads spinners and error messages all over the code, and each request still starts only after its component renders, which is the waterfall from part 1. React has a better place for loading and error UI, and the router can start requests before any component renders at all.

## Suspense for data

The Re-rendering and Performance lesson used `Suspense` with `lazy()`: while a component's code is still downloading, the nearest `<Suspense>` above it shows its `fallback` instead. Data works the same way. `useSuspenseQuery` takes the same options as `useQuery`, but while the data isn't ready, the component **suspends**: it stops rendering, and the nearest `Suspense` boundary shows its fallback. When the data arrives, React renders the component again, and this time `data` is always there. There's no `isPending` branch, and TypeScript knows `data` is never undefined.

The loading UI moves up to wherever you put the boundary. One boundary around a whole section shows one placeholder for everything in it, which looks calmer than five spinners popping in one by one.

## Error boundaries for failures

A suspense query that fails throws its error during rendering, and the nearest **error boundary**, the component from the Routing and App Structure lesson that catches errors thrown below it and shows a fallback instead, takes over. For a section of a page, the `react-error-boundary` package gives you an `ErrorBoundary` component to wrap it in, with a `fallbackRender` function that draws the fallback. It hands that function `resetErrorBoundary`, which clears the error and renders the children again.

A retry button needs one more piece. TanStack Query remembers that the query failed, so rendering again would only throw the same error. `useQueryErrorResetBoundary()` gives a `reset` function that clears that memory, and passing it as the boundary's `onReset` makes Try again really fetch again.

## Start in the loader

The Routing and App Structure lesson's loaders run before their route renders, which is the earliest moment the app knows what a page needs: the click itself. A loader can start a query there with the same `queryOptions` the component uses:

- `queryClient.ensureQueryData(productQuery(slug))` returns the cached product if there's one, and otherwise fetches and caches it. Awaiting it makes the navigation wait for the product, so the page never renders without its main data.
- `queryClient.prefetchInfiniteQuery(reviewsQuery(slug))`, not awaited, starts the reviews request and moves on. The page appears as soon as the product is ready, and the reviews section suspends until its own data arrives.

Both requests now start together, at the click, so the waterfall is gone. In the component, `useSuspenseQuery(productQuery(slug))` finds the product already in the cache, under the same key, so it renders at once with no second request. That's why the options live in one function: the loader and the component can't disagree about the key.

The route itself, in `src/app/router.tsx`, names the loader next to the component:

```tsx sketch
{
  path: "products/:slug",
  loader: productLoader,
  Component: ProductPage,
  ErrorBoundary: RouteError,
},
```

## When the loader fails

If the product doesn't exist, `ensureQueryData` throws the `ApiError` for the 404, and the router shows the route's error boundary, as the Routing and App Structure lesson explained. Inside it, `useRouteError()` returns that same `ApiError`, so the page can say this product doesn't exist rather than something went wrong:

```tsx
import { useRouteError } from "react-router";
import { ApiError } from "@/lib/api";

export function RouteError() {
  const error = useRouteError();
  if (error instanceof ApiError && error.status === 404) {
    return <h1>We couldn't find that product.</h1>;
  }
  return <h1>Something went wrong. Try reloading the page.</h1>;
}
```

## Which to use where

Use a loader with `ensureQueryData` for what a page can't show without, like the product on its own page. Prefetch, without waiting, what can arrive a moment later, like reviews further down the page. Use `useSuspenseQuery` with a `Suspense` and an `ErrorBoundary` around each section that loads on its own. Keep plain `useQuery` for small pieces that shouldn't hold up anything around them, like the card in part 3, or a converted price in part 6.

examples.code:
import type { LoaderFunctionArgs } from "react-router";
import { queryClient } from "@/app/queryClient";
import { reviewsQuery } from "@/features/reviews";
import { productQuery } from "./queries";

export async function productLoader({ params }: LoaderFunctionArgs) {
  const slug = params.slug ?? "";
  void queryClient.prefetchInfiniteQuery(reviewsQuery(slug));
  await queryClient.ensureQueryData(productQuery(slug));
  return null;
}

// src/features/products/ProductPage.tsx
import { Suspense } from "react";
import { useQueryErrorResetBoundary, useSuspenseQuery } from "@tanstack/react-query";
import { ErrorBoundary } from "react-error-boundary";
import { useParams } from "react-router";
import { ReviewList } from "@/features/reviews";
import { formatPrice } from "@/lib/format";
import { productQuery } from "./queries";

export function ProductPage() {
  const slug = useParams().slug ?? "";
  const { data: product } = useSuspenseQuery(productQuery(slug));
  const { reset } = useQueryErrorResetBoundary();

  return (
    <article>
      <h1>{product.name}</h1>
      <p>{formatPrice(product.priceCents)}</p>
      <p>{product.description}</p>

      <ErrorBoundary
        onReset={reset}
        fallbackRender={({ resetErrorBoundary }) => (
          <div role="alert">
            <p>The reviews didn't load.</p>
            <button type="button" onClick={resetErrorBoundary}>Try again</button>
          </div>
        )}
      >
        <Suspense fallback={<p>Loading reviews…</p>}>
          <ReviewList slug={slug} />
        </Suspense>
      </ErrorBoundary>
    </article>
  );
}

import { useMutation } from "@tanstack/react-query";
import { setCartItem } from "./api";
import { cartQuery } from "./queries";
import type { Cart } from "./schemas";

type QuantityChange = { slug: string; quantity: number };

function withQuantity(cart: Cart, { slug, quantity }: QuantityChange): Cart {
  const items = cart.items.map((item) =>
    item.slug === slug ? { ...item, quantity, lineTotalCents: item.priceCents * quantity } : item,
  );
  return { ...cart, items, subtotalCents: items.reduce((sum, item) => sum + item.lineTotalCents, 0) };
}

export function useSetQuantity() {
  return useMutation({
    mutationFn: ({ slug, quantity }: QuantityChange) => setCartItem(slug, quantity),

    onMutate: async (change, { client }) => {
      await client.cancelQueries({ queryKey: cartQuery.queryKey });
      const previous = client.getQueryData(cartQuery.queryKey);
      if (previous) client.setQueryData(cartQuery.queryKey, withQuantity(previous, change));
      return { previous };
    },

    onError: (_error, _change, result, { client }) => {
      if (result?.previous) client.setQueryData(cartQuery.queryKey, result.previous);
    },

    onSettled: (_cart, _error, _change, _result, { client }) =>
      client.invalidateQueries({ queryKey: cartQuery.queryKey }),
  });
}

import { ApiError } from "@/lib/api";
import type { CartItem } from "./schemas";
import { useSetQuantity } from "./useSetQuantity";

type QuantityPickerProps = { item: CartItem };

export function QuantityPicker({ item }: QuantityPickerProps) {
  const setQuantity = useSetQuantity();
  const error = setQuantity.error;
  const available = error instanceof ApiError && error.status === 409 ? error.problem.available : undefined;

  return (
    <div>
      <label htmlFor={`qty-${item.slug}`}>Quantity</label>
      <select
        id={`qty-${item.slug}`}
        value={item.quantity}
        onChange={(event) => setQuantity.mutate({ slug: item.slug, quantity: Number(event.target.value) })}
      >
        {Array.from({ length: 10 }, (_, i) => i + 1).map((n) => (
          <option key={n} value={n}>{n}</option>
        ))}
      </select>
      {typeof available === "number" && <p role="alert">Only {available} left in stock.</p>}
      {error && typeof available !== "number" && <p role="alert">Couldn't change the quantity.</p>}
    </div>
  );
}

import { useSuspenseInfiniteQuery } from "@tanstack/react-query";
import { reviewsQuery } from "./queries";

type ReviewListProps = { slug: string };

export function ReviewList({ slug }: ReviewListProps) {
  const { data, hasNextPage, fetchNextPage, isFetchingNextPage } = useSuspenseInfiniteQuery(reviewsQuery(slug));
  const reviews = data.pages.flatMap((page) => page.items);

  if (reviews.length === 0) return <p>No reviews yet. Be the first.</p>;

  return (
    <section aria-labelledby="reviews-heading">
      <h2 id="reviews-heading">Reviews</h2>
      <ul>
        {reviews.map((review) => (
          <li key={review.id}>
            <h3>{review.title}</h3>
            <p>{review.rating} of 5, by {review.author.name}</p>
            <p>{review.body}</p>
          </li>
        ))}
      </ul>
      {hasNextPage && (
        <button type="button" onClick={() => fetchNextPage()} disabled={isFetchingNextPage}>
          {isFetchingNextPage ? "Loading…" : "Show more reviews"}
        </button>
      )}
    </section>
  );
}

import { queryOptions } from "@tanstack/react-query";
import { z } from "zod";

const RATES_URL = "https://api.frankfurter.dev/v2/rates?base=USD&quotes=EUR,GBP";

const Rates = z.array(
  z.object({
    date: z.string(),
    base: z.literal("USD"),
    quote: z.string(),
    rate: z.number().positive(),
  }),
);

export const ratesQuery = queryOptions({
  queryKey: ["exchange-rates", "USD"],
  queryFn: async ({ signal }) => {
    const response = await fetch(RATES_URL, { signal: AbortSignal.any([signal, AbortSignal.timeout(5_000)]) });
    if (!response.ok) throw new Error(`Exchange rates answered ${response.status}`);
    return Rates.parse(await response.json());
  },
  staleTime: 60 * 60 * 1000,
  retry: 1,
});

import { useQuery } from "@tanstack/react-query";
import { ratesQuery } from "./rates";

type LocalPriceProps = { cents: number; currency: "EUR" | "GBP" };

export function LocalPrice({ cents, currency }: LocalPriceProps) {
  const { data: rates } = useQuery(ratesQuery);
  const rate = rates?.find((r) => r.quote === currency)?.rate;

  if (rate === undefined) return null;

  const amount = new Intl.NumberFormat("en", { style: "currency", currency }).format((cents / 100) * rate);
  return <span className="local-price">about {amount}</span>;
}
